1	// ArgumentParser -- a port of the CPython 3.12 `argparse.ArgumentParser`
2	// scanning machinery: `add_argument`, `parse_known_args`, `_parse_known_args`,
3	// `_parse_optional`, `_get_option_tuples`, `_match_argument`, `_get_values` and
4	// `error`/`exit`. Layout and wrapping live in formatter.mjs; this module only
5	// decides *what* each token means and *when* each action fires.
6	
7	import { getArgv, getProgName, writeStdout, writeStderr, exit, getTerminalColumns } from '../py/sys.mjs';
8	import { PyValueError, PyTypeError } from '../py/errors.mjs';
9	import { reprStr, pyStr } from '../py/repr.mjs';
10	import { StoreAction, HelpAction, SUPPRESS } from './actions.mjs';
11	import { ArgumentError, ArgumentTypeError, getActionName } from './errors.mjs';
12	import { formatUsage, formatHelp } from './formatter.mjs';
13	
14	/**
15	 * CPython `_ActionsContainer._negative_number_matcher`:
16	 * `re.compile(r'^-\d+$|^-\d*\.\d+$')`. Two Python-isms are reproduced here:
17	 *   * `\d` in a `str` pattern is Unicode-aware, hence `\p{Nd}` (so `-٥` is a
18	 *     number and therefore a positional, not an unknown option);
19	 *   * Python's `$` also matches immediately before a *trailing newline*, hence
20	 *     the `\n?` (verified: `--b $'-5\n'` is accepted as --b's value).
21	 */
22	const NEGATIVE_NUMBER_MATCHER = /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;
23	
24	/** CPython registers this under ('type', None): the default `type=` callable. */
25	function identity(string) {
26	  return string;
27	}
28	
29	/** CPython's ('action', name) registry, reduced to the actions this port ships. */
30	const ACTION_CLASSES = new Map([
31	  ['store', StoreAction],
32	  ['help', HelpAction],
33	]);
34	
35	function resolveActionClass(name) {
36	  if (name === undefined || name === null) return StoreAction; // registry entry for None
37	  if (typeof name === 'function') return name; // an Action subclass passed directly
38	  const cls = ACTION_CLASSES.get(name);
39	  if (cls === undefined) throw new PyValueError(`unknown action ${reprStr(String(name))}`);
40	  return cls;
41	}
42	
43	/** Python `repr()` over the value kinds a `choices=` list can hold. */
44	function reprValue(value) {
45	  return typeof value === 'string' ? reprStr(value) : pyStr(value);
46	}
47	
48	/** Python `hasattr(namespace, dest)` for a namespace modelled as a plain object. */
49	function hasDest(namespace, dest) {
50	  return Object.prototype.hasOwnProperty.call(namespace, dest);
51	}
52	
53	/**
54	 * CPython `HelpFormatter._get_nargs_pattern`. The parser matches token
55	 * *classifications* -- 'A' (plain argument), 'O' (option) and '-' (the `--`
56	 * separator) -- against a regex built from the action's nargs, which is how
57	 * "does this option have a value after it?" is decided.
58	 */
59	function getNargsPattern(action) {
60	  const { nargs } = action;
61	  let pattern;
62	  if (nargs === null || nargs === undefined) pattern = '(-*A-*)'; // exactly one
63	  else if (nargs === '?') pattern = '(-*A?-*)';
64	  else if (nargs === '*') pattern = '(-*[A-]*)';
65	  else if (nargs === '+') pattern = '(-*A[A-]*)';
66	  else pattern = `(-*${Array.from({ length: nargs }, () => 'A').join('-*')}-*)`;
67	
68	  // For optionals, '--' may not appear among the consumed tokens: CPython drops
69	  // every '-' from the pattern, so nargs=0 collapses to '()' and nargs=None to
70	  // '(A)'. That is why `--a --` reports "expected one argument".
71	  if (action.optionStrings.length > 0) {
72	    pattern = pattern.replaceAll('-*', '').replaceAll('-', '');
73	  }
74	  return pattern;
75	}
76	
77	/** CPython's `nargs_errors` table in `_match_argument`. */
78	function nargsErrorMessage(nargs) {
79	  if (nargs === null || nargs === undefined) return 'expected one argument';
80	  if (nargs === '?') return 'expected at most one argument';
81	  if (nargs === '+') return 'expected at least one argument';
82	  return `expected ${nargs} argument${nargs === 1 ? '' : 's'}`;
83	}
84	
85	export class ArgumentParser {
86	  constructor(options = {}) {
87	    // CPython: prog = os.path.basename(sys.argv[0]).
88	    this.prog = options.prog ?? getProgName();
89	    this.prefixChars = options.prefixChars ?? '-';
90	    this.exitOnError = options.exitOnError ?? true;
91	
92	    this._actions = [];
93	    // Insertion-ordered, like CPython's `_option_string_actions` dict; the order
94	    // decides how prefix matches are listed in an "ambiguous option" message.
95	    this._optionStringActions = new Map();
96	    this._hasNegativeNumberOptionals = false;
97	
98	    // The two default containers of an ArgumentParser, in display order.
99	    this._positionalsGroup = { title: 'positional arguments', actions: [] };
100	    this._optionalsGroup = { title: 'options', actions: [] };
101	    this._actionGroups = [this._positionalsGroup, this._optionalsGroup];
102	
103	    // CPython adds -h/--help before any user argument when add_help is true.
104	    if (options.addHelp ?? true) {
105	      const p = this.prefixChars[0];
106	      this.addArgument([`${p}h`, `${p}${p}help`], {
107	        action: 'help',
108	        default: SUPPRESS,
109	        help: 'show this help message and exit',
110	      });
111	    }
112	  }
113	
114	  /* ------------------------------------------------------------ building --- */
115	
116	  /**
117	   * CPython `_ActionsContainer.add_argument`. `names` is one option string or a
118	   * list of them ('-h', '--help'); a single name that does not start with a
119	   * prefix char declares a positional instead.
120	   */
121	  addArgument(names, options = {}) {
122	    const nameList = typeof names === 'string' ? [names] : [...names];
123	    const kwargs = { ...options };
124	    const isPositional = nameList.length === 1 && !this.prefixChars.includes(nameList[0][0]);
125	
126	    let optionStrings;
127	    let dest;
128	    if (isPositional) {
129	      // CPython `_get_positional_kwargs`: a positional is required unless its
130	      // nargs makes it skippable.
131	      optionStrings = [];
132	      [dest] = nameList;
133	      const nargs = kwargs.nargs ?? null;
134	      kwargs.required = !(nargs === '?' || nargs === '*')
135	        || (nargs === '*' && kwargs.default === undefined);
136	    } else {
137	      // CPython `_get_optional_kwargs`: dest comes from the first long option
138	      // ('--foo-bar' -> 'foo_bar'), falling back to the first short one.
139	      optionStrings = nameList;
140	      for (const optionString of optionStrings) {
141	        if (!this.prefixChars.includes(optionString[0])) {
142	          throw new PyValueError(
143	            `invalid option string ${reprStr(optionString)}: must start with a character `
144	            + `${reprStr(this.prefixChars)}`,
145	          );
146	        }
147	      }
148	      dest = kwargs.dest ?? null;
149	      if (dest === null) {
150	        const long = optionStrings.find((s) => s.length > 1 && this.prefixChars.includes(s[1]));
151	        let stripped = long ?? optionStrings[0];
152	        while (stripped.length > 0 && this.prefixChars.includes(stripped[0])) {
153	          stripped = stripped.slice(1);
154	        }
155	        if (stripped === '') {
156	          throw new PyValueError(`dest= is required for options like ${reprStr(optionStrings[0])}`);
157	        }
158	        dest = stripped.replaceAll('-', '_');
159	      }
160	    }
161	
162	    const actionClass = resolveActionClass(kwargs.action);
163	    delete kwargs.action;
164	    delete kwargs.dest;
165	    // ('type', None) resolves to `identity` in CPython's registry.
166	    const action = new actionClass({ ...kwargs, optionStrings, dest, type: kwargs.type ?? identity });
167	
168	    // CPython computes the default metavar lazily in the HelpFormatter
169	    // (`_get_default_metavar_for_optional` -> dest.upper(), positional -> dest).
170	    // Materialising it here keeps the formatter a pure layout function. nargs=0
171	    // actions never show a metavar, so -h stays `[-h]`.
172	    if (action.metavar === null && action.nargs !== 0) {
173	      action.metavar = optionStrings.length > 0 ? dest.toUpperCase() : dest;
174	    }
175	
176	    return this._addAction(action);
177	  }
178	
179	  /** CPython `_ActionsContainer._add_action` plus `_check_conflict`. */
180	  _addAction(action) {
181	    for (const optionString of action.optionStrings) {
182	      if (this._optionStringActions.has(optionString)) {
183	        throw new ArgumentError(action, `conflicting option string: ${optionString}`);
184	      }
185	    }
186	    this._actions.push(action);
187	    for (const optionString of action.optionStrings) {
188	      this._optionStringActions.set(optionString, action);
189	      // Remembering whether any option *looks* like a negative number decides
190	      // whether '-3' is read as a value or as an unknown option.
191	      if (NEGATIVE_NUMBER_MATCHER.test(optionString)) this._hasNegativeNumberOptionals = true;
192	    }
193	    const group = action.optionStrings.length > 0 ? this._optionalsGroup : this._positionalsGroup;
194	    group.actions.push(action);
195	    return action;
196	  }
197	
198	  /* ------------------------------------------------------------- parsing --- */
199	
200	  /** CPython `parse_args`: parse, then refuse to ignore leftover tokens. */
201	  parseArgs(args = null) {
202	    const [namespace, extras] = this.parseKnownArgs(args);
203	    if (extras.length > 0) {
204	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
205	    }
206	    return namespace;
207	  }
208	
209	  /** CPython `parse_known_args`: seed defaults, scan, convert ArgumentError to error(). */
210	  parseKnownArgs(args = null) {
211	    const argStrings = args === null || args === undefined ? getArgv() : [...args];
212	
213	    // The namespace is a plain object keyed by dest; a SUPPRESS default (as on
214	    // -h/--help) means "never put this dest in the namespace at all".
215	    const namespace = {};
216	    for (const action of this._actions) {
217	      if (action.dest !== SUPPRESS && !hasDest(namespace, action.dest)
218	          && action.defaultValue !== SUPPRESS) {
219	        namespace[action.dest] = action.defaultValue;
220	      }
221	    }
222	
223	    if (!this.exitOnError) {
224	      return this._parseKnownArgs(argStrings, namespace);
225	    }
226	    try {
227	      return this._parseKnownArgs(argStrings, namespace);
228	    } catch (err) {
229	      // CPython: `except ArgumentError: self.error(str(err))` -- the action name
230	      // prefix is already baked into the message by ArgumentError itself.
231	      if (err instanceof ArgumentError) return this.error(err.message);
232	      throw err;
233	    }
234	  }
235	
236	  /** CPython `_parse_known_args`: the left-to-right scan itself. */
237	  _parseKnownArgs(argStrings, namespace) {
238	    // -- Pass 1: classify every token. 'O' = option, 'A' = argument, '-' = the
239	    // `--` separator. Everything after the first `--` is forced to 'A'; `--`
240	    // itself stays in the token list and is only dropped later, by a positional
241	    // action consuming it (_get_values).
242	    const optionStringIndices = new Map();
243	    const patternParts = [];
244	    for (let i = 0; i < argStrings.length; i += 1) {
245	      const argString = argStrings[i];
246	      if (argString === '--') {
247	        patternParts.push('-');
248	        for (let j = i + 1; j < argStrings.length; j += 1) patternParts.push('A');
249	        break;
250	      }
251	      const optionTuple = this._parseOptional(argString);
252	      if (optionTuple === null) {
253	        patternParts.push('A');
254	      } else {
255	        optionStringIndices.set(i, optionTuple);
256	        patternParts.push('O');
257	      }
258	    }
259	    const argStringsPattern = patternParts.join('');
260	
261	    const seenActions = new Set();
262	    const extras = [];
263	    let positionals = this._actions.filter((action) => action.optionStrings.length === 0);
264	
265	    // Convert an action's raw tokens and fire it. Conversion happening *here*,
266	    // mid-scan, is why `--a abc --b` reports the invalid int rather than --b's
267	    // missing value.
268	    const takeAction = (action, argumentStrings, optionString) => {
269	      seenActions.add(action);
270	      const argumentValues = this._getValues(action, argumentStrings);
271	      if (argumentValues !== SUPPRESS) {
272	        action.call(this, namespace, argumentValues, optionString);
273	      }
274	    };
275	
276	    // CPython `consume_optional`.
277	    const consumeOptional = (startIndex) => {
278	      let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);
279	      const actionTuples = [];
280	      let stop;
281	
282	      // Loops so that a single-dash cluster (`-hx`) can yield several actions.
283	      for (;;) {
284	        if (action === null) {
285	          // Unknown option: keep the token verbatim for the caller to report.
286	          extras.push(argStrings[startIndex]);
287	          return startIndex + 1;
288	        }
289	
290	        if (explicitArg !== null) {
291	          const argCount = this._matchArgument(action, 'A');
292	
293	          if (argCount === 0 && sep !== '=' && !this.prefixChars.includes(optionString[1])
294	              && explicitArg !== '') {
295	            // Single-dash option that takes no argument: run it, then re-read
296	            // the tail as further short options ('-hx' -> '-h' then '-x').
297	            // `sep !== '='` is what keeps '-h=x' out of this branch.
298	            actionTuples.push([action, [], optionString]);
299	            const char = optionString[0];
300	            optionString = char + explicitArg[0];
301	            if (this._optionStringActions.has(optionString)) {
302	              action = this._optionStringActions.get(optionString);
303	              explicitArg = explicitArg.slice(1);
304	              if (explicitArg === '') {
305	                sep = null;
306	                explicitArg = null;
307	              } else if (explicitArg[0] === '=') {
308	                sep = '=';
309	                explicitArg = explicitArg.slice(1);
310	              } else {
311	                sep = '';
312	              }
313	            } else {
314	              // The re-split produced an unknown option; the actions collected
315	              // so far still run (this is why '-hx' prints help).
316	              extras.push(char + explicitArg);
317	              stop = startIndex + 1;
318	              break;
319	            }
320	          } else if (argCount === 1) {
321	            stop = startIndex + 1;
322	            actionTuples.push([action, [explicitArg], optionString]);
323	            break;
324	          } else {
325	            // e.g. '--help=x': a zero-argument long option given a value.
326	            throw new ArgumentError(action, `ignored explicit argument ${reprStr(explicitArg)}`);
327	          }
328	        } else {
329	          // No '=' argument: take the following tokens, but only as many as the
330	          // action's nargs pattern matches against their classifications.
331	          const start = startIndex + 1;
332	          const argCount = this._matchArgument(action, argStringsPattern.slice(start));
333	          stop = start + argCount;
334	          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
335	          break;
336	        }
337	      }
338	
339	      for (const [act, values, optStr] of actionTuples) takeAction(act, values, optStr);
340	      return stop;
341	    };
342	
343	    // CPython `consume_positionals`: greedily hand tokens to the positionals
344	    // that are still unfilled. With no positional actions this is a no-op that
345	    // returns startIndex unchanged, which is what leaves `--` in the leftovers.
346	    const consumePositionals = (startIndex) => {
347	      const argCounts = this._matchArgumentsPartial(positionals, argStringsPattern.slice(startIndex));
348	      let index = startIndex;
349	      for (let k = 0; k < argCounts.length; k += 1) {
350	        const args = argStrings.slice(index, index + argCounts[k]);
351	        index += argCounts[k];
352	        takeAction(positionals[k], args, null);
353	      }
354	      positionals = positionals.slice(argCounts.length);
355	      return index;
356	    };
357	
358	    // -- Pass 2: alternate positionals and optionals until past the last option.
359	    const indices = [...optionStringIndices.keys()];
360	    const maxOptionStringIndex = indices.length > 0 ? Math.max(...indices) : -1;
361	    let startIndex = 0;
362	    while (startIndex <= maxOptionStringIndex) {
363	      const nextOptionStringIndex = Math.min(...indices.filter((i) => i >= startIndex));
364	      if (startIndex !== nextOptionStringIndex) {
365	        const positionalsEndIndex = consumePositionals(startIndex);
366	        if (positionalsEndIndex > startIndex) {
367	          startIndex = positionalsEndIndex;
368	          continue;
369	        }
370	        startIndex = positionalsEndIndex;
371	        if (startIndex !== nextOptionStringIndex) {
372	          extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
373	          startIndex = nextOptionStringIndex;
374	        }
375	      }
376	      startIndex = consumeOptional(startIndex);
377	    }
378	    const stopIndex = consumePositionals(startIndex);
379	    extras.push(...argStrings.slice(stopIndex));
380	
381	    // -- Required actions. This runs before the caller's unrecognized-arguments
382	    // check, so a missing --a beats a stray token; -h has already exited by now.
383	    const requiredActions = [];
384	    for (const action of this._actions) {
385	      if (seenActions.has(action)) continue;
386	      if (action.required) {
387	        requiredActions.push(getActionName(action));
388	      } else if (typeof action.defaultValue === 'string' && hasDest(namespace, action.dest)
389	                 && namespace[action.dest] === action.defaultValue) {
390	        // CPython converts a string default only now, so `type=` is never called
391	        // twice and never called at all when the argument was supplied.
392	        namespace[action.dest] = this._getValue(action, action.defaultValue);
393	      }
394	    }
395	    if (requiredActions.length > 0) {
396	      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
397	    }
398	
399	    return [namespace, extras];
400	  }
401	
402	  /**
403	   * CPython `_parse_optional`. Returns null when the token is a positional, or
404	   * the 4-tuple [action, optionString, sep, explicitArg]; `action` is null for a
405	   * token that looks like an option but matches nothing.
406	   */
407	  _parseOptional(argString) {
408	    // 1. empty string -> positional.
409	    if (argString === '') return null;
410	    // 2. does not start with a prefix char -> positional.
411	    if (!this.prefixChars.includes(argString[0])) return null;
412	    // 3. exact match.
413	    if (this._optionStringActions.has(argString)) {
414	      return [this._optionStringActions.get(argString), argString, null, null];
415	    }
416	    // 4. a lone prefix char ('-') -> positional.
417	    if (argString.length === 1) return null;
418	    // 5. '--opt=value' where '--opt' is known.
419	    const eq = argString.indexOf('=');
420	    if (eq !== -1) {
421	      const optionString = argString.slice(0, eq);
422	      if (this._optionStringActions.has(optionString)) {
423	        return [this._optionStringActions.get(optionString), optionString, '=', argString.slice(eq + 1)];
424	      }
425	    }
426	    // 6. abbreviations / single-dash clusters.
427	    const optionTuples = this._getOptionTuples(argString);
428	    if (optionTuples.length > 1) {
429	      const options = optionTuples.map((tuple) => tuple[1]).join(', ');
430	      this.error(`ambiguous option: ${argString} could match ${options}`);
431	    } else if (optionTuples.length === 1) {
432	      return optionTuples[0];
433	    }
434	    // 7. negative numbers are values unless an option is spelled like one.
435	    if (NEGATIVE_NUMBER_MATCHER.test(argString) && !this._hasNegativeNumberOptionals) return null;
436	    // 8. anything containing a space was meant to be a value.
437	    if (argString.includes(' ')) return null;
438	    // 9. an option, but an unknown one.
439	    return [null, argString, null, null];
440	  }
441	
442	  /** CPython `_get_option_tuples`: every interpretation of an abbreviated option. */
443	  _getOptionTuples(optionString) {
444	    const result = [];
445	    const chars = this.prefixChars;
446	
447	    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
448	      // Long options are only ever split at '='; the rest is a prefix to match.
449	      const eq = optionString.indexOf('=');
450	      const optionPrefix = eq === -1 ? optionString : optionString.slice(0, eq);
451	      const sep = eq === -1 ? null : '=';
452	      const explicitArg = eq === -1 ? null : optionString.slice(eq + 1);
453	      for (const [known, action] of this._optionStringActions) {
454	        if (known.startsWith(optionPrefix)) result.push([action, known, sep, explicitArg]);
455	      }
456	    } else if (chars.includes(optionString[0])) {
457	      // Single-dash: either '-x' with 'yz' glued on, or an abbreviation of a
458	      // longer single-dash option.
459	      const shortOptionPrefix = optionString.slice(0, 2);
460	      const shortExplicitArg = optionString.slice(2);
461	      for (const [known, action] of this._optionStringActions) {
462	        if (known === shortOptionPrefix) result.push([action, known, '', shortExplicitArg]);
463	        else if (known.startsWith(optionString)) result.push([action, known, null, null]);
464	      }
465	    }
466	
467	    return result;
468	  }
469	
470	  /** CPython `_match_argument`: how many following tokens this action takes. */
471	  _matchArgument(action, argStringsPattern) {
472	    const match = new RegExp(`^${getNargsPattern(action)}`).exec(argStringsPattern);
473	    if (match === null) {
474	      throw new ArgumentError(action, nargsErrorMessage(action.nargs));
475	    }
476	    return match[1].length;
477	  }
478	
479	  /**
480	   * CPython `_match_arguments_partial`: try the positionals as a whole, then
481	   * progressively fewer of them, and return the token count each one gets.
482	   */
483	  _matchArgumentsPartial(actions, argStringsPattern) {
484	    for (let i = actions.length; i > 0; i -= 1) {
485	      const pattern = actions.slice(0, i).map(getNargsPattern).join('');
486	      const match = new RegExp(`^${pattern}`).exec(argStringsPattern);
487	      if (match !== null) return match.slice(1).map((group) => group.length);
488	    }
489	    return [];
490	  }
491	
492	  /** CPython `_get_values`: turn the matched tokens into the stored value. */
493	  _getValues(action, argStrings) {
494	    const strings = [...argStrings];
495	    // `arg_strings.remove('--')`: a positional swallowing the separator drops it.
496	    const separator = strings.indexOf('--');
497	    if (separator !== -1) strings.splice(separator, 1);
498	
499	    // A single token for a one-value action produces a scalar; every other
500	    // shape (including the empty list of a nargs=0 action) produces a list.
501	    if (strings.length === 1 && (action.nargs === null || action.nargs === '?')) {
502	      const value = this._getValue(action, strings[0]);
503	      this._checkValue(action, value);
504	      return value;
505	    }
506	    const values = strings.map((string) => this._getValue(action, string));
507	    for (const value of values) this._checkValue(action, value);
508	    return values;
509	  }
510	
511	  /** CPython `_get_value`: run `type=` and translate its failures. */
512	  _getValue(action, argString) {
513	    const typeFunc = action.type ?? identity;
514	    try {
515	      return typeFunc(argString);
516	    } catch (err) {
517	      // CPython catches ArgumentTypeError, TypeError and ValueError here and
518	      // names the type via `action.type.__name__` -- hence `int`/`str` being
519	      // declared as named functions in types.mjs.
520	      if (err instanceof ArgumentTypeError || err instanceof PyValueError
521	          || err instanceof PyTypeError) {
522	        throw new ArgumentError(action, `invalid ${typeFunc.name} value: ${reprStr(argString)}`);
523	      }
524	      throw err;
525	    }
526	  }
527	
528	  /** CPython `_check_value`: enforce `choices=`. */
529	  _checkValue(action, value) {
530	    if (action.choices !== null && !action.choices.includes(value)) {
531	      const choices = action.choices.map(reprValue).join(', ');
532	      throw new ArgumentError(
